using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace Stackshot
{
    static class SurfaceConsistencyTests
    {
        static System.Collections.Generic.IEnumerable<Control> Children(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(var c in Children(child))yield return c;}}
        static void Click(Button button){typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        [DllImport("user32.dll")]static extern int GetWindowLong(IntPtr window,int index);
        static void IsBrand(Icon icon,Action<bool,string> check){using(var image=icon.ToBitmap()){var c=image.GetPixel(image.Width/2,image.Height/2);check(c.B>180&&c.R<60,"generic icon instead of capture artwork");}}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("surfaces/RGB default migrates missing fields and preserves explicit HEX preference",delegate{check(new Preferences().ColorFormat=="RGB"&&ColorValues.Format(Color.Red,null,true)=="rgb(255, 0, 0)"&&ColorValues.Format(Color.Red,"invalid",true)=="rgb(255, 0, 0)","RGB defaults incomplete");var store=new PreferenceStore(Path.Combine(output,"rgb-default"));Directory.CreateDirectory(store.DirectoryPath);File.WriteAllText(store.FilePath,"{\"Version\":1}");check(store.Load().ColorFormat=="RGB","legacy missing field not migrated");store.Save(new Preferences{ColorFormat="HEX"});check(store.Load().ColorFormat=="HEX","explicit saved preference overwritten");});
            run("surfaces/custom choice supports keyboard selection and paints clean closed capsule",delegate{using(var owner=new Form{AutoScaleMode=AutoScaleMode.None})using(var choice=new PreferencesChoice("RGB","HEX","HSL")){owner.Controls.Add(choice);check(choice.AccessibleRole==AccessibleRole.ComboBox&&choice.SelectedIndex==0,"semantic or initial value");choice.ApplyKey(Keys.Down);check(choice.SelectedIndex==1,"down");choice.ApplyKey(Keys.Up);check(choice.SelectedIndex==0,"up");choice.ApplyKey(Keys.End);check(choice.SelectedItem=="HSL","end");choice.ApplyKey(Keys.Home);check(choice.SelectedIndex==0&&!choice.ApplyKey(Keys.Tab),"home or trapped Tab");using(var image=UiPaintingTests.NativePaint(choice,Color.Magenta)){image.Save(Path.Combine(output,"choice-capsule-native.png"));check(image.GetPixel(0,0).ToArgb()==Color.White.ToArgb(),"native rectangular frame remains");}check(!choice.Visible,"choice shown");}});
            run("surfaces/choice options route actual menu callbacks to settings save and defaults",delegate{Preferences saved=null;using(var dialog=new SettingsDialog(new Preferences(),"fixture",delegate(Preferences p){saved=p;return "keep hidden";})){var controls=Children(dialog).ToArray();check(!controls.OfType<ComboBox>().Any(),"native ComboBox still in settings");var choice=controls.OfType<PreferencesChoice>().Single(c=>c.AccessibleName=="取色格式");var upper=controls.OfType<PreferencesSwitch>().Single(c=>c.AccessibleName=="HEX 使用大写字母");check(!upper.Enabled,"HEX-only option active for RGB");using(var menu=choice.CreateOptions()){check(menu.Renderer is CraftMenuRenderer&&menu.Items.OfType<ToolStripMenuItem>().Single(i=>i.Text==ColorFormatSettings.Labels[0]).Checked,"unshared popup or missing check");menu.Items.OfType<ToolStripMenuItem>().Single(i=>i.Text==ColorFormatSettings.Labels[1]).PerformClick();}check(choice.SelectedIndex==1&&upper.Enabled,"option did not select or enable uppercase");Click(controls.OfType<Button>().Single(b=>b.Text=="保存并应用"));check(saved.ColorFormat=="HEX","custom selector not saved");Click(controls.OfType<Button>().Single(b=>b.Text=="恢复默认"));check(choice.SelectedIndex==0&&!upper.Enabled&&!dialog.Visible,"defaults not RGB or window shown");}});
            run("surfaces/group child rows preserve rounded corner background without native region clipping",delegate{using(var owner=new Form{AutoScaleMode=AutoScaleMode.None})using(var group=new PreferencesGroup{Width=400}){group.AddRow(new PreferencesRow("第一行",new Label{Text="value"}));group.AddRow(new PreferencesRow("第二行",new Label{Text="value"}));owner.Controls.Add(group);check(group.Region==null,"binary window-region clipping remains");using(var image=UiPaintingTests.NativePaint(group,Color.Magenta)){using(var g=Graphics.FromImage(image))foreach(Control row in group.Controls)using(var child=UiPaintingTests.NativePaint(row,Color.Magenta))g.DrawImageUnscaled(child,row.Location);image.Save(Path.Combine(output,"rounded-group-native-composite.png"));foreach(var p in new[]{new Point(1,1),new Point(image.Width-2,1),new Point(1,image.Height-2),new Point(image.Width-2,image.Height-2)}){var c=image.GetPixel(p.X,p.Y);check(Math.Abs(c.R-PreferencesLook.Background.R)<3&&Math.Abs(c.B-PreferencesLook.Background.B)<3,"white row protrudes through corner "+p);}}check(!owner.Visible,"group shown");}});
            run("surfaces/popups remove native frame styles and share full-surface renderer",delegate{using(var menu=TrayActions.Create(delegate{return new Preferences();},delegate{})){var handle=menu.Handle;check((GetWindowLong(handle,-16)&0x00800000)==0&&(GetWindowLong(handle,-20)&0x301)==0,"extra native frame styles remain");menu.Items.OfType<CraftMenuItem>().Single(i=>i.Name=="settings").Select();using(var image=menu.RenderOffscreen())image.Save(Path.Combine(output,"tray-menu-unified-native.png"));check(!menu.Visible,"menu shown");}});
            run("identity/embedded multiresolution icon and native executable icon use shared artwork",delegate{using(var stream=typeof(TrayBrand).Assembly.GetManifestResourceStream("ScreenCraft.AppIcon.ico"))using(var reader=new BinaryReader(stream)){check(reader.ReadUInt16()==0&&reader.ReadUInt16()==1&&reader.ReadUInt16()==8,"missing eight-size ICO resource");}using(var native=Icon.ExtractAssociatedIcon(Application.ExecutablePath)){IsBrand(native,check);using(var image=native.ToBitmap())image.Save(Path.Combine(output,"exe-icon-native.png"));}using(var icon=TrayBrand.Create())IsBrand(icon,check);using(var artwork=BrandArtwork.Render(256))artwork.Save(Path.Combine(output,"app-icon-artwork.png"));});
            run("identity/settings editor OCR and pin windows share application icon",delegate{using(var settings=new SettingsDialog(new Preferences(),"fixture",delegate{return "unused";}))using(var editor=new CraftEditor(new Bitmap(100,100)))using(var ocr=new OcrResultWindow(new Bitmap(100,100),"auto")){IsBrand(settings.Icon,check);IsBrand(editor.Icon,check);IsBrand(ocr.Icon,check);check(!settings.Visible&&!editor.Visible&&!ocr.Visible,"identity check showed windows");}});
            run("surfaces/settings and open choice use actual production painting without desktop",delegate{using(var dialog=new SettingsDialog(new Preferences(),"fixture",delegate{return "unused";})){using(var image=dialog.RenderSyntheticPreview(4))image.Save(Path.Combine(output,"settings-color-unified-offscreen.png"));using(var image=dialog.RenderSyntheticPreview(5))image.Save(Path.Combine(output,"settings-about-unified-offscreen.png"));var choice=Children(dialog).OfType<PreferencesChoice>().Single(c=>c.AccessibleName=="取色格式");using(var options=choice.CreateOptions())using(var image=options.RenderOffscreen())image.Save(Path.Combine(output,"choice-options-native.png"));check(!dialog.Visible,"preview showed settings");}});
        }
    }
}
